import type { CardData } from "@twotoe/writer/card";

// Example briefs bundled into the build (generated by scripts/gen-examples.ts
// from synthetic fixtures). Bundled, not fetched: the hosted demo makes no
// network request beyond its own files.
const modules = import.meta.glob<CardData>("./example/*.json", { eager: true, import: "default" });

export interface Example {
  slug: string;     // "f22"
  name: string;     // "Kitchen sink"
  data: CardData;
}

const ORDER: Array<[string, string]> = [["f22", "Kitchen sink"], ["f06", "Railway user"], ["f23", "Clean night"]];

export const EXAMPLES: Example[] = ORDER.flatMap(([slug, name]) => {
  const entry = Object.entries(modules).find(([path]) => path.includes(`/${slug}-`));
  return entry ? [{ slug, name, data: entry[1] }] : [];
});

export function isCardData(v: unknown): v is CardData {
  const d = v as CardData;
  return Boolean(d && typeof d === "object" && d.brief && typeof d.brief.line1 === "string" && Array.isArray(d.findings) && Array.isArray(d.advisories));
}

// Local mode: `twotoe card` serves ./brief.json. Anywhere else this 404s and
// the card shows the examples.
export async function loadLocal(fetchImpl: typeof fetch = fetch): Promise<CardData | null> {
  try {
    const r = await fetchImpl("./brief.json", { cache: "no-store" });
    if (!r.ok) return null;
    const j: unknown = await r.json();
    return isCardData(j) ? j : null;
  } catch {
    return null;
  }
}
